    public Map<String, Object> parseWsTrade(Map<String, Object> trade, Map<String, Object> market)
    {
        //
        //     {
        //         "base": "usdt",
        //         "quote": "twd",
        //         "side": "ask",
        //         "price": "32.039",
        //         "volume": "1",
        //         "fee": "6407800",
        //         "feeCurrency": "twd",
        //         "transactionTimestamp": 1694667358,
        //         "eventTimestamp": 1694667358,
        //         "orderID": 390733918,
        //         "orderType": "LIMIT",
        //         "matchID": "bd07673a-94b1-419e-b5ee-d7b723261a5d",
        //         "isMarket": false,
        //         "isMaker": false
        //     }
        //
        String id = this.safeString(trade, "matchID");
        String orderId = this.safeString(trade, "orderID");
        Long timestamp = this.safeTimestamp(trade, "transactionTimestamp");
        String baseId = this.safeString(trade, "base");
        String quoteId = this.safeString(trade, "quote");
        String base = this.safeCurrencyCode((String) (baseId));
        String quote = this.safeCurrencyCode((String) (quoteId));
        String symbol = this.symbol(Helpers.add((base + "/"), quote));
        market = (Map<String, Object>) (this.safeMarket(symbol, market));
        String price = this.safeString(trade, "price");
        String type = this.safeStringLower(trade, "orderType");
        String side = this.safeString(trade, "side");
        if (!java.util.Objects.equals(side, null))
        {
            if (java.util.Objects.equals(side, "ask"))
            {
                side = "sell";
            } else if (java.util.Objects.equals(side, "bid"))
            {
                side = "buy";
            }
        }
        String amount = this.safeString(trade, "volume");
        Map<String, Object> fee = null;
        String feeAmount = this.safeString(trade, "fee");
        String feeSymbol = this.safeCurrencyCode(this.safeString(trade, "feeCurrency"));
        if (!java.util.Objects.equals(feeAmount, null))
        {
            final String finalFeeAmount = feeAmount;
            fee = new HashMap<String, Object>() {{
                put( "cost", finalFeeAmount );
                put( "currency", feeSymbol );
                put( "rate", null );
            }};
        }
        Boolean isMaker = (Boolean) this.safeBool(trade, "isMaker");
        String takerOrMaker = null;
        if (!java.util.Objects.equals(isMaker, null))
        {
            if (java.util.Objects.equals(isMaker, true))
            {
                takerOrMaker = "maker";
            } else
            {
                takerOrMaker = "taker";
            }
        }
        final String finalTakerOrMaker = takerOrMaker;
        final String finalSide = side;
        final Map<String, Object> finalFee = fee;
        return (Map<String, Object>) (this.safeTrade((Map<String, Object>) (new HashMap<String, Object>() {{
            put( "id", id );
            put( "info", trade );
            put( "order", orderId );
            put( "timestamp", timestamp );
            put( "datetime", Bitopro.this.iso8601(timestamp) );
            put( "symbol", symbol );
            put( "takerOrMaker", finalTakerOrMaker );
            put( "type", type );
            put( "side", finalSide );
            put( "price", price );
            put( "amount", amount );
            put( "cost", null );
            put( "fee", finalFee );
        }}), market));
    }
